package main

import (
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"
)

func TestProbeUserCap(t *testing.T) {
	store := NewStoreWithCap(30*time.Second, 2)
	now := time.Unix(1000, 0)
	store.now = func() time.Time { return now }
	store.Create("a", "alice")
	now = time.Unix(1001, 0)
	store.Create("b", "alice")
	now = time.Unix(1002, 0)
	_, err := store.Create("c", "alice")
	if !errors.Is(err, ErrUserAtCap) {
		t.Fatalf("third session error = %v, want ErrUserAtCap", err)
	}
	if store.Len() != 2 {
		t.Fatalf("capped create mutated store: len = %d", store.Len())
	}

	// A different user is unaffected.
	now = time.Unix(1003, 0)
	if _, err := store.Create("d", "bob"); err != nil {
		t.Fatalf("other user blocked: %v", err)
	}

	// Expiry frees capacity: a expires at 1060.
	now = time.Unix(1061, 0)
	if _, err := store.Create("e", "alice"); err != nil {
		t.Fatalf("create after expiry blocked: %v", err)
	}

	// Zero cap means unlimited.
	unlimited := NewStore(time.Hour)
	for i := 0; i < 5; i++ {
		if _, err := unlimited.Create(fmt.Sprintf("u%d", i), "carol"); err != nil {
			t.Fatalf("unlimited store blocked at %d: %v", i, err)
		}
	}

	// Handler: 429 on cap.
	now = time.Unix(1100, 0)
	handler := sessionHandler(store)
	rec := httptest.NewRecorder()
	req := httptest.NewRequest("POST", "/session?id=f&user=bob", nil)
	req.Header.Set("Content-Type", "application/json")
	handler(rec, req)
	_ = rec
	rec = httptest.NewRecorder()
	req = httptest.NewRequest("POST", "/session?id=g&user=nobody", nil)
	req.Header.Set("Content-Type", "application/json")
	handler(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("uncapped user status = %d, want 200", rec.Code)
	}
}
EOF
